// A split-flap clock: the hours and the minutes each on a big flap, split
// across the middle with the hinge pins showing, and the date on three small
// flaps underneath. It draws on the minute.
import { WEEKDAYS, MONTHS, two, secondsToNextMinute } from './time'

const LOOKS: Record<string, { back: string; backEdge: string; top: string; topLow: string; bottom: string; bottomLow: string; ink: string; split: string; pin: string; tag: string }> = {
  black: { back: '#1d1d1d', backEdge: '#0a0a0a', top: '#323232', topLow: '#262626', bottom: '#222222', bottomLow: '#1a1a1a', ink: '#ece8df', split: '#050505', pin: '#555555', tag: '#a8a49b' },
  cream: { back: '#d9d2c4', backEdge: '#b5ad9c', top: '#fbf8f1', topLow: '#efe9dd', bottom: '#e9e3d6', bottomLow: '#ddd5c6', ink: '#232323', split: '#8f8778', pin: '#a69e8e', tag: '#6c665c' },
  red: { back: '#211c1b', backEdge: '#0c0a0a', top: '#c5372c', topLow: '#b02e24', bottom: '#a52a21', bottomLow: '#93241c', ink: '#fff4e8', split: '#3a0d09', pin: '#6e2a24', tag: '#ffd9cf' },
}

const FONT = 'Liberation Sans'

// One flap: two halves split across the middle, the text over both.
function flap(id: string, x: number, y: number, w: number, h: number, text: string, size: number, look: any, tag?: string) {
  const r = Math.min(w, h) * 0.07
  const mid = y + h / 2
  const f = (n: number) => n.toFixed(1)
  const topHalf = `M${f(x)} ${f(mid)} V${f(y + r)} A${f(r)} ${f(r)} 0 0 1 ${f(x + r)} ${f(y)} H${f(x + w - r)} A${f(r)} ${f(r)} 0 0 1 ${f(x + w)} ${f(y + r)} V${f(mid)} Z`
  const bottomHalf = `M${f(x)} ${f(mid)} V${f(y + h - r)} A${f(r)} ${f(r)} 0 0 0 ${f(x + r)} ${f(y + h)} H${f(x + w - r)} A${f(r)} ${f(r)} 0 0 0 ${f(x + w)} ${f(y + h - r)} V${f(mid)} Z`
  const split = Math.max(1.5, h * 0.012)
  const pinW = Math.max(2, w * 0.018)
  const pinH = h * 0.09
  return (
    <g>
      <linearGradient id={`${id}-top`} gradientUnits="userSpaceOnUse" x1="0" y1={y} x2="0" y2={mid}>
        <stop offset="0" stopColor={look.top} />
        <stop offset="1" stopColor={look.topLow} />
      </linearGradient>
      <linearGradient id={`${id}-bottom`} gradientUnits="userSpaceOnUse" x1="0" y1={mid} x2="0" y2={y + h}>
        <stop offset="0" stopColor={look.bottom} />
        <stop offset="1" stopColor={look.bottomLow} />
      </linearGradient>
      <rect x={x + w * 0.01} y={y + h * 0.035} width={w} height={h} rx={r} fill="#000000" opacity={0.35} />
      <path d={topHalf} fill={`url(#${id}-top)`} />
      <path d={bottomHalf} fill={`url(#${id}-bottom)`} />
      <text x={x + w / 2} y={mid + size * 0.36} fontFamily={FONT} fontWeight={700} fontSize={size} fill={look.ink} textAnchor="middle">
        {text}
      </text>
      <rect x={x} y={mid} width={w} height={h / 2} fill="#000000" opacity={0.07} />
      <rect x={x} y={mid - split / 2} width={w} height={split} fill={look.split} />
      <rect x={x} y={mid + split / 2} width={w} height={Math.max(1, split * 0.5)} fill="#ffffff" opacity={0.06} />
      <rect x={x - pinW * 0.4} y={mid - pinH / 2} width={pinW} height={pinH} rx={pinW * 0.4} fill={look.pin} />
      <rect x={x + w - pinW * 0.6} y={mid - pinH / 2} width={pinW} height={pinH} rx={pinW * 0.4} fill={look.pin} />
      {tag ? (
        <text x={x + w * 0.06} y={y + h * 0.13} fontFamily={FONT} fontWeight={700} fontSize={h * 0.075} fill={look.tag}>
          {tag}
        </text>
      ) : null}
    </g>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const look = LOOKS[app.config.theme] || LOOKS.black
  const twelve = app.config.clock === '12h'
  const showDate = String(app.config.showDate) !== 'false'
  const now = new Date()
  frameos.setNextSleep(secondsToNextMinute(now))

  const hours = now.getHours()
  const hourText = twelve ? String(hours % 12 || 12) : two(hours)
  const minuteText = two(now.getMinutes())
  const tag = twelve ? (hours < 12 ? 'AM' : 'PM') : undefined

  const portrait = H > W * 1.1
  const pad = Math.min(W, H) * 0.07
  const gap = Math.min(W, H) * 0.045
  const dateShare = showDate ? 0.22 : 0
  const flaps = []
  let cardW
  let cardH
  let top
  if (!portrait) {
    cardW = (W - pad * 2 - gap) / 2
    cardH = Math.min(cardW * 0.98, (H - pad * 2) * (1 - dateShare) - (showDate ? gap : 0))
    top = (H - cardH - (showDate ? gap + cardH * 0.3 : 0)) / 2
    const size = Math.min(cardH * 0.78, cardW * 0.74)
    flaps.push(flap('h', pad, top, cardW, cardH, hourText, size, look, tag))
    flaps.push(flap('m', pad + cardW + gap, top, cardW, cardH, minuteText, size, look))
  } else {
    cardW = W - pad * 2
    cardH = Math.min(cardW * 0.8, ((H - pad * 2) * (1 - dateShare * 0.8) - gap * (showDate ? 2 : 1)) / 2)
    top = (H - cardH * 2 - gap - (showDate ? gap + cardH * 0.3 : 0)) / 2
    const size = Math.min(cardH * 0.78, cardW * 0.74)
    flaps.push(flap('h', pad, top, cardW, cardH, hourText, size, look, tag))
    flaps.push(flap('m', pad, top + cardH + gap, cardW, cardH, minuteText, size, look))
  }

  if (showDate) {
    const smallH = cardH * 0.3
    const bottomOfClock = portrait ? top + cardH * 2 + gap : top + cardH
    const y = bottomOfClock + gap
    const parts = [WEEKDAYS[now.getDay()].substring(0, 3).toUpperCase(), String(now.getDate()), MONTHS[now.getMonth()].substring(0, 3).toUpperCase()]
    const widths = [smallH * 1.9, smallH * 1.3, smallH * 1.9]
    const smallGap = gap * 0.45
    const total = widths[0] + widths[1] + widths[2] + smallGap * 2
    let x = (W - total) / 2
    parts.forEach((text, i) => {
      flaps.push(flap(`d${i}`, x, y, widths[i], smallH, text, smallH * 0.55, look))
      x += widths[i] + smallGap
    })
  }

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <radialGradient id="back" gradientUnits="userSpaceOnUse" cx={W / 2} cy={H * 0.45} r={Math.max(W, H) * 0.75}>
        <stop offset="0" stopColor={look.back} />
        <stop offset="1" stopColor={look.backEdge} />
      </radialGradient>
      <rect width={W} height={H} fill="url(#back)" />
      {flaps}
    </svg>
  )
}

